217: const pieceValue={p:100,n:320,b:335,r:500,q:900,k:20000};
218: function evaluate(state){
219:   let score=0;
220:   for(let i=0;i<64;i++){const p=state.board[i];if(!p)continue;const [f,r]=coords(i),advance=p.color==='b'?r:7-r;
221:     let positional=0;if(p.type==='p')positional=(p.color==='b'?r:7-r)*7+(3.5-Math.abs(3.5-f))*2;
222:     if(p.type==='n'||p.type==='b')positional=(3.5-Math.abs(3.5-f))*(p.type==='n'?7:4)+(3.5-Math.abs(3.5-r))*(p.type==='n'?7:4);
223:     if(p.type==='k'&&state.fullmove>12)positional=(3.5-Math.abs(3.5-f))*(3.5-Math.abs(3.5-r))*2;
224:     score+=(p.color==='b'?1:-1)*(pieceValue[p.type]+positional);
225:   }
