228: function scoreMove(state,m){
229:   const p=state.board[m.from],victim=m.ep?{type:'p'}:state.board[m.to];let s=victim?pieceValue[victim.type]*10-pieceValue[p.type]:0;
230:   if(m.promotion)s+=800;if(m.castle)s+=45;
231:   const next=applyMove(state,m).state;if(inCheck(next,next.turn))s+=35;
232:   const [f,r]=coords(m.to);s+=(3.5-Math.abs(3.5-f))+(3.5-Math.abs(3.5-r));
233:   return s+(Math.random()-.5)*8;
