237:   moves.sort((a,b)=>scoreMove(state,b)-scoreMove(state,a));let best=-Infinity,choice=moves[0];
238:   for(const move of moves.slice(0,7)){
239:     const next=applyMove(state,move).state,reply=allMoves(next);let value=evaluate(next);
240:     if(reply.length){let worst=Infinity;for(const response of reply){const result=applyMove(next,response).state;worst=Math.min(worst,evaluate(result));}value=worst;}
241:     value+=scoreMove(state,move)*.08+(Math.random()-.5)*4;
242:     if(value>best){best=value;choice=move;}
243:   }
244:   return choice;
245: }
